    "rule \"ReDoS\" severity=\"Medium\" {     sinks {         sink \"Regex.new\" {             fix \"Use a non-backtracking regex engine or simplify nested quantifiers\"         }         sink \"Regex.compile\" {             fix \"Use a non-backtracking regex engine or simplify nested quantifiers\"         }         sink \"re.compile\" {             fix \"re.compile(regex, timeout=1) or simplify nested quantifiers\"         }         sink \"regexp.compile\" {             fix \"Use a non-backtracking regex engine or simplify nested quantifiers\"         }     }     conditions {         check_args_contain \"+)+\"         check_args_contain \"+)*\"         check_args_contain \"*)+\"         check_args_contain \"*)*\"         check_args_contain \"?)\"     }     message \"Potential ReDoS: regex with nested quantifiers or overlapping groups. Catastrophic backtracking risk.\" } ";
    "// Rust-specific security rules // Covers SSRF, command injection, path traversal, unsafe code // All rules scoped to Rust only — does not apply to other languages  rule \"RustUnsafeBlock\" severity=\"High\" {     languages { include \"rust\" }     // Detect unsafe blocks that may need auditing     sinks {         sink \"unsafe\" {             fix \"Review unsafe block for memory safety issues. Document invariants.\"         }     }     message \"Unsafe block without documented safety invariants\" }  rule \"RustCommandInjection\" severity=\"High\" {     languages { include \"rust\" }     // Command injection via std::process::Command     sinks {         sink \"Command::new\" arg=0 {             sanitizer \"String::from\"             sanitizer \".to_string()\"             sanitizer \"std::path::Path::new\"         }         sink \"Command::arg\" arg=0 {             sanitizer \"String::from\"             sanitizer \".to_string()\"         }         sink \"Command::args\" arg=0 {             sanitizer \".to_string()\"         }     }     sources {         source \"std::env::var\"         source \"std::env::args\"     }     message \"Potential command injection via Command::new() with user input\" }  rule \"RustPathTraversal\" severity=\"Medium\" {     languages { include \"rust\" }     // Path traversal via fs operations     sinks {         sink \"fs::read\" arg=0         sink \"fs::read_to_string\" arg=0         sink \"fs::write\" arg=0         sink \"fs::create_dir\" arg=0         sink \"fs::remove_file\" arg=0         sink \"std::fs::File::open\" arg=0 {             sanitizer \"std::path::Path::new\"             sanitizer \"std::path::PathBuf::from\"         }     }     sources {         source \"std::env::var\"         source \"request\"         source \"params\"     }     message \"Potential path traversal via filesystem operation\" }  rule \"RustSSRF\" severity=\"High\" {     languages { include \"rust\" }     // SSRF via HTTP clients     sinks {         sink \"reqwest::blocking::get\" arg=0 {             sanitizer \"Url::parse\"             sanitizer \"reqwest::Url\"         }         sink \"reqwest::get\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"reqwest::post\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"ureq::get\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"ureq::post\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"attohttpc::get\" arg=0 {             sanitizer \"Url::parse\"         }     }     sources {         source \"std::env::var\"         source \"request\"         source \"params\"         source \"user_url\"     }     message \"Potential SSRF via HTTP client with user-controlled URL\" }  rule \"RustIntegerOverflow\" severity=\"Medium\" {     languages { include \"rust\" }     // Integer overflow in release mode (wraps silently)     sinks {         sink \"+\" {             sanitizer \"checked_add\"             sanitizer \"saturating_add\"             sanitizer \"wrapping_add\"         }         sink \"-\" {             sanitizer \"checked_sub\"             sanitizer \"saturating_sub\"             sanitizer \"wrapping_sub\"         }         sink \"*\" {             sanitizer \"checked_mul\"             sanitizer \"saturating_mul\"             sanitizer \"wrapping_mul\"         }     }     message \"Integer operation may overflow silently in release mode\" }  rule \"RustPanicInLibrary\" severity=\"Medium\" {     languages { include \"rust\" }     // panic!, unwrap(), expect() in library code     sinks {         sink \"panic\" {             fix \"Return Result<T, E> instead of panicking\"         }         sink \"unwrap\" {             fix \"Use ? operator or provide default value with unwrap_or()\"         }         sink \"expect\" {             fix \"Return Result or use unwrap_or() with proper error message\"         }     }     message \"Panic-inducing code in library code\" }  rule \"RustHardcodedCredentials\" severity=\"High\" {     languages { include \"rust\" }     // Hardcoded passwords, API keys, tokens     sinks {         sink \"password\" {             fix \"Use environment variable or secrets manager\"         }         sink \"api_key\" {             fix \"Use environment variable or secrets manager\"         }         sink \"secret\" {             fix \"Use environment variable or secrets manager\"         }         sink \"token\" {             fix \"Use environment variable or secrets manager\"         }     }     message \"Potential hardcoded credential\" } ";
    "rule \"ScentLeakage\" severity=\"Critical\" {     sinks {         // Crystal log sinks         sink \"Logger.info\" {             // URLs validated through SSRF checks are safe to log (diagnostic info)             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.warn\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.error\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.debug\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.notice\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.info\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.warn\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.error\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.debug\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.notice\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         // Crystal output sinks         sink \"puts\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"pp!\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"print\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDOUT.puts\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDOUT.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDERR.puts\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDERR.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"Log.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid logging sensitive data — redact or mask\"         }         sink \"IO.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid writing sensitive data to unsecured output — redact or mask\"         }     }     sources {         source \"password\"         source \"token\"         source \"secret\"         source \"api_key\"         source \"credential\"         source \"email\"         source \"ssn\"         source \"credit_card\"         source \"session_id\"     }     message \"Scent Leakage: sensitive data may reach {sink} via scented variable(s): {tainted_vars}.\" }";
    "rule \"SQLInjection\" severity=\"Critical\" {     sinks {         sink \"db.exec\" arg=0 {             fix \"Use parameterized queries: db.exec(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.query\" arg=0 {             fix \"Use parameterized queries: db.query(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.scalar\" arg=0 {             fix \"Use parameterized queries: db.scalar(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.query_one\" arg=0 {             fix \"Use parameterized queries: db.query_one(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.query_all\" arg=0 {             fix \"Use parameterized queries: db.query_all(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.execute\" arg=0 {             fix \"Use parameterized queries: db.execute(\\\"INSERT ... VALUES ($1)\\\", [{arg0}])\"         }         sink \"database.exec\" arg=0 {             fix \"Use parameterized queries instead of string interpolation\"         }         sink \"database.query\" arg=0 {             fix \"Use parameterized queries instead of string interpolation\"         }     }     sources {         source \"params\"         source \"query\"         source \"user_input\"         source \"request\"     }     message \"Potential SQL injection via {sink} with tainted argument(s): {tainted_vars}.\" } ";
    "rule \"SSRF\" severity=\"High\" {     sinks {         sink \"HTTP::Client.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"URI.encode\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"HTTP::Client.get(URI.parse({arg0}))\"         }         sink \"HTTP::Client.post\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"HTTP::Client.post(URI.parse({arg0}))\"         }         sink \"HTTP::Client.put\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before HTTP request: allowlisted_url?(arg0)\"         }         sink \"HTTP::Client.patch\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before HTTP request: allowlisted_url?({arg0})\"         }         sink \"HTTP::Client.delete\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before HTTP request: allowlisted_url?({arg0})\"         }         sink \"HTTP::Client.exec\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before HTTP request: allowlisted_url?({arg0})\"         }         sink \"client.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"URI.encode\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"client.get(URI.parse({arg0}))\"         }         sink \"client.post\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"client.post(URI.parse({arg0}))\"         }         sink \"client.put\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before request: allowlisted_url?({arg0})\"         }         sink \"client.delete\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before request: allowlisted_url?({arg0})\"         }         sink \"client.exec\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL before request: allowlisted_url?({arg0})\"         }         sink \"http.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"URI.encode\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"http.get(URI.parse({arg0}))\"         }         sink \"http.post\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"http.post(URI.parse({arg0}))\"         }         sink \"http_client.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"URI.encode\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"http_client.get(URI.parse({arg0}))\"         }         sink \"conn.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"URI.encode\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"conn.get(URI.parse({arg0}))\"         }         sink \"connection.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"URI.encode\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"connection.get(URI.parse({arg0}))\"         }         sink \"Crest::Request.execute\" arg=1 {             // Crest::Request.execute(url, ...) - URL is arg 1 (0-indexed)             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"valid_url?\"             fix \"Validate URL with allowlist before Crest::Request.execute\"         }         sink \"Crest.get\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Crest.get(URI.parse({arg0}))\"         }         sink \"Crest.post\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Crest.post(URI.parse({arg0}))\"         }         sink \"Crest.put\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Crest.put(URI.parse({arg0}))\"         }         sink \"Crest.delete\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Crest.delete(URI.parse({arg0}))\"         }         sink \"Crest.patch\" arg=0 {             sanitizer \"URI.parse\"             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Crest.patch(URI.parse({arg0}))\"         }         sink \"hackney.get\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL with allowlist before request\"         }         sink \"hackney.post\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL with allowlist before request\"         }         sink \"req.get\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL with allowlist before request\"         }         sink \"req.post\" arg=0 {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             fix \"Validate URL with allowlist before request\"         }     }     sources {         source \"params\" field=\"url\"         source \"request\" field=\"body\"         source \"user_url\"         source \"url\"         source \"query\"         source \"href\"         source \"uri\"     }     message \"Potential SSRF via {sink} with user-controlled URL\" }";
    "rule \"WeakCryptography\" severity=\"Medium\" {     sinks {         sink \"Digest::MD5\" {             fix \"Use Digest::SHA256.hexdigest or OpenSSL::Digest.new(\\\"sha256\\\")\"         }         sink \"Digest::SHA1\" {             fix \"Use Digest::SHA256.hexdigest or OpenSSL::Digest.new(\\\"sha256\\\")\"         }         sink \"hashlib.md5\" {             fix \"hashlib.sha256({arg0}) instead of hashlib.md5\"         }         sink \"hashlib.sha1\" {             fix \"hashlib.sha256({arg0}) instead of hashlib.sha1\"         }     }     conditions {         skip_taint_check     }     message \"Weak cryptography: {sink} uses a weak hashing algorithm (MD5/SHA1). Use SHA-256 or stronger.\" }  rule \"InsecureRandom\" severity=\"Low\" {     sinks {         sink \"int.random\" {             fix \"Use a CSPRNG for security contexts\"         }         sink \"float.random\" {             fix \"Use a CSPRNG for security contexts\"         }         sink \"list.random\" {             fix \"Use a CSPRNG for security contexts\"         }         sink \"Math.random\" {             fix \"Use crypto.getRandomValues() or a CSPRNG for security contexts\"         }         sink \"Random.rand\" {             fix \"Use SecureRandom.rand for security contexts\"         }         sink \"random\" {             sanitizer \"SecureRandom\"             sanitizer \"Secure\"             sanitizer \"Crypto\"             fix \"Use SecureRandom or a CSPRNG for security contexts\"         }     }     conditions {         skip_taint_check     }     message \"Insecure random: {sink} may use a non-cryptographic PRNG. Use SecureRandom for security contexts.\" } ";
  ] in
  String.concat "\n" rules
